int tld_rng_set_seed(struct rng_state *s, uint64_t seed)
{
        uint64_t sanity = 0U;
        uint64_t z = 0U;

        s->gen = 0;
        s->z1 = 0.0F;
        s->gauss = 0.0;
        s->has_gauss = 0;

        ASSERT(s != NULL, "No rng allocated in set seed");
        while(!sanity){
                sanity = 0;
                z = (seed += 0x9e3779b97f4a7c15);
                z = (z ^ (z >> 30U)) * 0xbf58476d1ce4e5b9;
                z = (z ^ (z >> 27U)) * 0x94d049bb133111eb;
                s->s[0] = z ^ (z >> 31U);
                if(s->s[0]){
                        sanity++;
                }
                z = (seed += 0x9e3779b97f4a7c15);
                z = (z ^ (z >> 30U)) * 0xbf58476d1ce4e5b9;
                z = (z ^ (z >> 27U)) * 0x94d049bb133111eb;
                s->s[1] = z ^ (z >> 31U);
                if(s->s[1]){
                        sanity++;
                }

                z = (seed += 0x9e3779b97f4a7c15);
                z = (z ^ (z >> 30U)) * 0xbf58476d1ce4e5b9;
                z = (z ^ (z >> 27U)) * 0x94d049bb133111eb;
                s->s[2] = z ^ (z >> 31U);
                if(s->s[2]){
                        sanity++;
                }

                z = (seed += 0x9e3779b97f4a7c15);
                z = (z ^ (z >> 30U)) * 0xbf58476d1ce4e5b9;
                z = (z ^ (z >> 27U)) * 0x94d049bb133111eb;
                s->s[3] = z ^ (z >> 31U);
                if(s->s[3]){
                        sanity++;
                }
        }

        return OK;
ERROR:
        return FAIL;
}

int init_rng_from_rng(struct rng_state** target, struct rng_state* rng)
{
        struct rng_state* s = NULL;
        int i = 0;
        MMALLOC_ALIGNED(s, sizeof(struct rng_state), _Alignof(struct rng_state));

        for(i = 0; i < 4;i++){
                s->s[i] = rng->s[i];
                s->gen = 0;
                s->z1 = 0.0;
                s->gauss = rng->gauss;
                s->has_gauss = rng->has_gauss;

        }
        jump(rng);
        *target = s;
        return OK;
ERROR:
        return FAIL;
}


