int work_queue_expand(struct work_queue *q, int add)
{
        ASSERT(q != NULL,"No work queue");
        int old_size;
        if(add == 0){
                add = q->n_alloc/ 2;
        }


        old_size = q->n_alloc;
        q->n_alloc += add;

        MREALLOC(q->l, sizeof(struct work_item*) * q->n_alloc);
        for(int i = old_size; i < q->n_alloc;i++){
                q->l[i] = NULL;
                RUN(work_item_alloc(&q->l[i]));
        }
        return OK;
ERROR:
        work_queue_free(q);
        return FAIL;
}

