#define SHUFFLE_FUNC(type)                                              \
        int tld_shuffle_##type(type* arr,int n, struct rng_state* rng)  \
        {                                                               \
                int r;                                                  \
                int i,j;                                                \
                type tmp;                                               \
                for (i = 0; i < n - 1; i++) {                           \
                        r = tl_random_int(rng,n);                       \
                        j = i +  r % (n-i);                             \
                        tmp = arr[j];                                   \
                        arr[j] = arr[i];                                \
                        arr[i] = tmp;                                   \
                }                                                       \
                return OK;                                              \
        }


